  'room.cocina.desc': '영양: 식사, 영양소, 수분, 주간 계획 기록.',
  'room.ejercicio.desc': '목표가 있는 근력·지구력·유연성 루틴.',
  'room.recamara.desc': '휴식 기록과 나만의 추억 노트 작성.',
  'room.descanso.desc': '밤하늘로 보는 수면: 일정, 알람, 점수와 밤 기록.',
  'room.anecdotario.desc': '나만의 추억 노트: 사진이 담긴 기억과 하루의 기분.',
  'room.despacho.desc': '재정: 고정·변동 지출과 수입으로 짜는 예산, 시뮬레이터가 있는 목표(재정 계산기, 저축·투자, 부채), 실시간 시세.',
  'room.biblioteca.desc': '대화형 백과사전: AI 채팅, 위키 항목과 학습 세션.',
  'room.entretenimiento.desc': '영화·드라마·책·보드게임 아카이브.',
  'room.sala.desc': '여행 계획: 일정, 비용, 체크리스트와 위시리스트.',
  'room.jardin.desc': '마음의 안정: 가이드 명상, 호흡과 감사 일기.',
  'room.garage.desc': '차량 정비와 서비스 관리.',
  'room.diario.desc': '카테고리별 매일 뉴스.',
  'room.hobbies.desc': '취미와 창작 프로젝트.',
  'room.idiomas.desc': '어학 학습: AI 선생님, 간격 반복 단어, 레벨별 커리큘럼과 연습문제.',
  'room.calendario.desc': '캘린더: 하루·주·월별 일정과 루틴.',
  'room.caminos.desc': '지도에 레이스 트랙, 철로, 롤러코스터 배치.',
  'room.canchas.desc': '지도에 축구·테니스·농구·야구 코트 배치.',
  'room.huerto.desc': '텃밭을 정리하고 씨앗을 심어 물을 주고 실시간으로 수확.',
  'room.granja.desc': '닭·돼지·염소·양·소·말을 기르고, 같은 에디터에서 사료도 재배.',
  'room.ideas.desc':
    '아이디어 일기와 브레인스토밍, 자유 캔버스 위의 10가지 개념도 형식(마인드맵, 트리, 타임라인, 사이클, 피라미드, 벤 다이어그램 등)과 결정에 쓰는 8가지 다이어그램(장단점 분석, 포스필드 분석, SWOT 분석, 아이젠하워 매트릭스, 의사결정 나무, 티어 리스트, 가중치 의사결정 매트릭스, 피시본 다이어그램)을 손으로 또는 AI로.',
  'room.metas.desc':
    '집 전체에서 마음먹은 것들: 하위 목표와 단계가 딸린 목표 목록, 목표마다 AI가 제안하는 계획(날짜가 붙은 단계가 그대로 진짜 하위 목표가 돼요), 그리고 모든 것이 시간축 위에서 제 기간을 차지하는 일정.',
  'room.computo.desc':
    '전산실: 공식집(수학·물리·화학 수록, 편집 가능)이 딸린 공학용 계산기와 8가지 모드――4가지 유형(2D·극좌표·매개변수·3D 곡면)의 그래프, 이진수와 16진수, 행렬, 연립방정식, 단위 변환, 팁 계산과 비례식――그리고 엑셀과 PDF로 내보낼 수 있는 스프레드시트.',
