  'ideas.tipoDesc.matriz': '정말로 중요하게 여기는 기준으로 여러 선택지를 점수 매겨요.',
  'ideas.guia.matriz':
    '각 기준은 나에게 얼마나 중요한지에 따라 가중치가 매겨지고(1~5), 각 선택지는 그 기준에서 1~5점을 받아요. 총점은 점수에 가중치를 곱한 값이라, 신경 쓰지 않는 기준에서 잘한다고 이길 수는 없어요.',
