  'ideas.matriz.criterioN': '기준 {n}',
  'ideas.matriz.opcionN': '선택지 {n}',
  'ideas.matriz.ayuda': '이름을 탭하면 바꿀 수 있고, 가중치를 탭하면 그 기준의 중요도를 올릴 수 있어요. 각 칸을 탭해서 1~5점을 매기세요. 총점은 이미 가중치를 곱한 값이에요.',
