  'ideas.ejemplo.chip': '예시',
  'ideas.ejemplo.comoFunciona': '이 형식은 어떻게 쓰나요?',
  'ideas.guia.mental': '마인드맵은 주제를 사방으로 펼쳐요. 가운데에 아이디어가 있고, 그 주위에 큰 가지들이, 가지마다 세부 내용이 매달려요. 순서를 정하기 전에 머릿속을 비우는 용도예요.',
  'ideas.guia.arbol': '트리는 조직도처럼 전체에서 세부로 나뉘어요. 흩어진 아이디어가 아니라 하위 범주로 나뉘는 분류를 다룰 때 사용하세요.',
  'ideas.guia.etimologia':
    '어원 트리는 단어를 분해해요. 어디서 왔는지, 무슨 뜻인지, 어떻게 쓰이는지, 같은 어족의 단어는 무엇인지 보여줘요. 브레인스토밍 전에 개념을 파고들거나 이름을 지을 때 유용해요.',
  'ideas.tipo.etimologia': '어원 트리',
  'ideas.tipoDesc.etimologia': '단어를 분해해요. 어원, 의미, 용법, 어족이에요.',
  'ideas.guia.llaves': '괄호형은 전체를 왼쪽에서 오른쪽으로 부분으로 나눠요. 고전적인 개요 형식이에요. 무언가를 분해해서 구성 요소를 살펴볼 때 좋아요.',
  'ideas.guia.circulo': '원형은 주제를 가운데 두고 아는 내용을 계층 없이 주위에 둘러싸요. 개념을 탐색하거나 시험 전 복습할 때 유용해요.',
  'ideas.guia.flujo': '순서도는 화살표로 단계를 연결해요. 단계를 탭하고 도형 버튼으로 시작, 분기, 끝으로 바꿀 수 있어요. 마름모는 예/아니오 질문이에요.',
  'ideas.guia.linea': '타임라인은 날짜순으로 정렬돼요. 중요한 사건은 선 위아래에 번갈아 배치되고, 세부 내용은 바깥쪽으로 뻗어요. 사건 앞에 연도를 적으면 그 자체로 읽기 편해요.',
  'ideas.guia.ciclo': '순환형은 반복되는 단계를 연결해요. 각 단계는 배경을 탭해서 뿌리부터 추가하세요. 이전 단계에 매달리지 않도록요. 그러면 저절로 원 둘레에 퍼져요.',
  'ideas.guia.piramide': '피라미드형은 단계를 쌓아 올려요. 각 단계는 아래 단계 위에 놓이니까, 기반부터 먼저 다져야 해요. 단계 이름을 두 번 탭하면 바꿀 수 있어요.',
  'ideas.guia.venn': '벤 다이어그램은 두 집합을 마주 놓고, 공통점은 겹치는 부분에 들어가요. 추가하기 전에 하단 바에서 영역을 고르거나, 항목을 다른 항목 위로 드래그하면 저절로 옮겨져요.',
  'ideas.guia.comparacion': '비교표는 두 주제를 열로 나누고 공통점은 가운데에 둬요. 표 형태의 벤 다이어그램이라, 항목이 많을 때 더 빨리 읽혀요.',
  'ideas.guia.proscontras': '각 항목은 1~5의 가중치를 가져요. 선택한 뒤 하단 바의 −＋로 조정하세요. 각 열 아래에 합계가 나오니까, "어느 목록이 더 기냐"로 정하지 않아도 돼요.',
  'ideas.guia.fuerzas': '역장 분석은 변화를 살펴봐요. 왼쪽에는 미는 힘, 오른쪽에는 막는 힘이 있고 각각 세기가 있어요. 오른쪽이 이기고 있다면 가장 무거운 힘부터 공략하세요.',
  'ideas.guia.foda': '강점과 약점은 나 자신의 것이고, 기회와 위협은 외부에서 와요. 헷갈릴 땐 그게 나에게 달린 일인지 아닌지 생각해 보세요.',
  'ideas.guia.eisenhower': '위쪽은 중요도, 왼쪽은 긴급도예요. "일정에 넣기" 사분면이 실제로 일을 진전시켜요. 여기가 계속 비어 있다면 하루 종일 불 끄기만 하는 거예요.',
  'ideas.guia.decision': '각 가지는 선택지와 그 결과를 나타내요. 뻔해 보여도 적어 두세요. 적지 않은 건 비교 대상조차 되지 못해요.',
  'ideas.guia.tier': 'S가 가장 좋고 D가 가장 나빠요. 아직 순위를 못 정한 건 아래 "미분류"에서 기다려요. 확실해지면 해당 행으로 드래그하세요.',
  'ideas.guia.ishikawa': '머리는 문제이고, 각 뼈는 원인의 갈래예요 (방법, 설비, 재료, 측정…). 찾아야 할 건 해결책이 아니라 원인이에요. 해결책은 나중이에요.',
