  'chat.manual.nota.cuartos': '방을 만들고 이름을 바꾸고 정리할 수 있어요. "삭제"를 하면 집에서 방이 없어져요.',
  'chat.manual.nota.despacho': 'AI를 사용하면 영수증 사진도 첨부할 수 있어요. 지출로 기록돼요.',
  'chat.manual.nota.diario': '그날의 문화 코너와 어시스턴트 배달에는 앱 안에서 AI가 쓰여요.',
  'chat.manual.nota.ejercicio': 'AI를 사용하면 일정에서 훈련 계획(✨ 버튼)을 만들 수 있고, 앱 안에서 운동 설명 이미지도 볼 수 있어요.',
  'chat.manual.nota.entretenimiento': '테이블 게임: 스네이크, 테트리스, 체스, 체커, 스도쿠, 메모리 게임, 퐁, 하키, 사이먼, 커넥트포, 스페이스, 공룡 게임…',
  'chat.manual.nota.garage': '타는 탈것(자전거, 오토바이, 자동차, UFO)은 "캐릭터와 탈것"에 있어요.',
  'chat.manual.nota.granja': '동물: 암탉, 돼지, 염소, 양, 소, 말. 음식에서 수확한 것을 먹어요.',
  'chat.manual.nota.hobbies': '일정에서 AI 계획(✨)을 요청하면 프로젝트를 진전시킬 수 있어요.',
  'chat.manual.nota.huerto': '작물: 당근, 상추, 해바라기, 토마토, 옥수수, 호박.',
  'chat.manual.nota.idiomas': '안에는 레벨별 회화 선생님, 채팅에서 만든 카드, 주제별 카드(AI)가 있어요.',
  'chat.manual.nota.configuraciones':
    '편집기의 설정 탭에 있는 모든 것: 언어, 외관(라이트, 다크, 투명), 아이콘 스타일, 인터페이스 테마와 글꼴, 패널 유리 효과, 지도의 비주얼 스타일(기본, 코믹, 미니어처, 레트로, 네온)과 그 효과, 알림, 백업.',
  'chat.manual.aviso.configuraciones': '로그인, 백업 복원, 데이터 삭제는 채팅에서 할 수 없어요. 어시스턴트가 해당 화면을 열어주면 직접 확인해야 해요.',
  'chat.manual.nota.interfaz':
    '집 테마, 하늘 배경, 배경 음악, Wrapped 연말 결산. 음악 분위기: calma, festivo, nocturno, chiptune, acogedor, energia, estudio, arcade, bosque, viaje, carrera, cajita.',
  'chat.manual.nota.mapa': '방향: 북, 남, 동, 서(위, 아래, 왼쪽, 오른쪽도 가능해요).',
  'chat.manual.nota.memoria': '어시스턴트는 세션이 바뀌어도 정보를 기억해요. 클립으로 사진을 첨부하거나 마이크로 말해서 입력할 수 있어요. @앱으로 기록 위치를 지정할 수 있어요.',
  'chat.manual.nota.objetos':
    'AI 없는 카탈로그: 램프, 의자, 테이블, 식물, 기타, 러그, 상자, 그림, 공, 책. 그 외에는 AI가 3D 모델로 만들어서 인벤토리에 저장해요. 2D 이미지는 "~ 이미지를 만들어줘"라고 요청하면 채팅에 남아요.',
  'chat.manual.nota.personaje':
    '의류: 모자, 안경... 부위: 머리, 몸통, 다리. 탈것: 자전거, 오토바이, 자동차, UFO(Space/Shift로 비행). 시점: 아이소메트릭, 3인칭, 1인칭(V 키).',
  'chat.manual.nota.sala': 'AI를 사용하면 새로운 장소가 자동으로 위치를 찾아 세계지도에 핀으로 표시돼요.',
  'chat.manual.nota.superficies': '색상: 빨강, 파랑, 초록... 또는 # 16진 코드. 바닥 재질과 지붕 모양은 편집기 카탈로그에서 골라요.',
  'chat.manual.nota.teclado': '키보드로 즐길 수 있는 단축키예요. 채팅에 입력하는 게 아니라 집 안에서 사용해요. 입력창에 글자를 쓰고 있거나 방이 열려 있을 때는 작동하지 않아요.',
  'chat.manual.notaSeccion.apps':
    '각 앱은 말하는 그대로 자기 데이터를 기록하고(@앱으로 기록 위치를 지정할 수 있어요), 이름을 부르면 메뉴가 열려요. "AI와 함께" 예시는 항상 AI 호출 1회를 소모해요(Pro 플랜 또는 직접 등록한 키). 커스텀 템플릿도 채팅으로 기록되고 이름으로 열려요. 참고: 오프라인 파서는 스페인어만 이해해서 한국어에서는 대부분의 명령이 AI를 거쳐요.',
  'chat.manual.notaSeccion.mapa': '정원, 농장, 트랙, 코트는 방 밖, 3D 지도 위에 있어요.',
